import re
files = list_files('reports/q2')
total = 0
for f in files:
    content = read_file(f)
    # content may be dict or list; find text
    if isinstance(content, dict):
        text = content.get('content') or content.get('text') or str(content)
    else:
        text = str(content)
    # find last TOTAL line
    m = None
    for line in text.splitlines():
        mm = re.match(r'\s*TOTAL:\s*([-\d.]+)', line)
        if mm:
            m = mm
    if m:
        total += float(m.group(1))
    else:
        print('NO TOTAL in', f, repr(text[:200]))
print(total)

