import json
offset = 0
ids = []
while True:
    r = list_tickets(status='open', priority='low', limit=100, offset=offset)
    items = r['items']
    for t in items:
        if t['customer'] == 'Fjord':
            ids.append(t['id'])
    if len(items) < 100 or offset + len(items) >= r['total']:
        break
    offset += len(items)
print("Fjord low open tickets:", ids)
for tid in ids:
    res = triage_ticket(tid, 'high')
    print(tid, '->', json.dumps(res)[:200])
